import { Field as FieldPrimitive } from '@ark-ui/solid/field';
import type { FieldSelectProps } from '@ark-ui/solid/field';
import { clsx } from 'clsx';
import type { JSX } from 'solid-js';
import { splitProps } from 'solid-js';
import { ChevronDownIcon } from '@/lib/moduix/icons/ui';
import styles from './NativeSelect.module.css';

type NativeSelectProps = FieldSelectProps & {
  controlProps?: JSX.HTMLAttributes<HTMLSpanElement>;
};

function NativeSelect(props: NativeSelectProps) {
  const [local, others] = splitProps(props, ['class', 'controlProps']);

  return (
    <span
      {...local.controlProps}
      data-scope="native-select"
      data-part="control"
      data-slot="native-select-control"
      class={clsx(styles.control, local.controlProps?.class)}
    >
      <FieldPrimitive.Select
        {...others}
        data-scope="field"
        data-part="select"
        data-slot="native-select-root"
        class={clsx(styles.root, local.class)}
      />
      <span
        aria-hidden="true"
        data-scope="native-select"
        data-part="indicator"
        data-slot="native-select-indicator"
        class={styles.indicator}
      >
        <ChevronDownIcon />
      </span>
    </span>
  );
}

export { NativeSelect };

@layer moduix.components {
  .control {
    --_select-action-size: var(--moduix-select-action-size, var(--moduix-size-xs));
    --_select-action-offset: var(--moduix-spacing-2);

    position: relative;
    display: inline-grid;
    width: fit-content;
    max-width: 100%;
    min-width: 0;
  }

  .root {
    box-sizing: border-box;
    width: var(--moduix-select-width, 14rem);
    max-width: 100%;
    min-width: 0;
    height: var(--moduix-select-control-height, var(--moduix-size-md));
    margin: 0;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-select-radius, var(--moduix-radius-md));
    padding-inline: var(--moduix-spacing-3-5)
      calc(var(--_select-action-offset) + var(--_select-action-size) + var(--moduix-spacing-3-5));
    appearance: none;
    background-color: var(--moduix-color-background);
    color: var(--moduix-color-foreground);
    font: inherit;
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: var(--moduix-focus-ring-inset-offset);
    cursor: pointer;
    transition:
      border-color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default),
      opacity var(--moduix-transition-default);

    &:focus-visible {
      border-color: var(--moduix-color-ring);
      outline-color: var(--moduix-color-ring);
    }

    &:is([data-invalid], [aria-invalid='true']) {
      border-color: var(--moduix-color-destructive);
      outline-color: var(--moduix-color-destructive);
    }

    &:is([data-disabled], :disabled) {
      pointer-events: none;
      opacity: var(--moduix-opacity-disabled);
    }

    &:is([multiple], [size]:not([size='0'], [size='1'])) {
      height: auto;
      padding-block: var(--moduix-spacing-2);
      padding-inline: var(--moduix-spacing-3-5);
      appearance: auto;
    }

    @media (forced-colors: active) {
      padding-inline-end: var(--moduix-spacing-3-5);
      appearance: auto;
    }
  }

  .indicator {
    position: absolute;
    top: 50%;
    inset-inline-end: var(--_select-action-offset);
    display: inline-flex;
    width: var(--_select-action-size);
    height: var(--_select-action-size);
    align-items: center;
    justify-content: center;
    border-radius: var(--moduix-radius-sm);
    color: var(--moduix-color-muted-foreground);
    pointer-events: none;
    transform: translateY(-50%);
    transition:
      background-color var(--moduix-transition-default),
      color var(--moduix-transition-default),
      opacity var(--moduix-transition-default);

    & > svg {
      width: var(--moduix-spacing-4);
      height: var(--moduix-spacing-4);
    }

    @media (forced-colors: active) {
      display: none;
    }
  }

  .root:is([data-disabled], :disabled) + .indicator {
    opacity: var(--moduix-opacity-disabled);
  }

  .root:hover + .indicator {
    @media (hover: hover) {
      background-color: var(--moduix-color-muted);
      color: var(--moduix-color-foreground);
    }
  }

  .root:is([multiple], [size]:not([size='0'], [size='1'])) + .indicator {
    display: none;
  }
}
